cd /tmp/sv-c937801baa7e4faea6108d3000ba0493/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -c "import sys,json; data=json.load(sys.stdin); json.dump(data,open('after-cpm-packages.json','w'),indent=2)" && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            key = f\"{pname} ({fw['framework']})\"
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(key, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b = extract_packages(baseline)
a = extract_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            changes.append((proj, pkg, bv, av))

if changes:
    print('VERSION CHANGES:')
    for proj, pkg, bv, av in changes:
        print(f'  {proj}: {pkg} {bv} -> {av}')
else:
    print('No unexpected version changes detected.')
"

